<script setup lang="ts">
import { onMounted, ref } from 'vue';import dayjs from 'dayjs';import { ElMessage, ElMessageBox } from 'element-plus';import { http } from '../api/http';import type { Booking } from '../types';const rows=ref<Booking[]>([]);async function load(){rows.value=(await http.get('/admin/approvals')).data}async function decide(row:Booking,action:'APPROVE'|'REJECT'){let comment='';if(action==='REJECT')comment=await ElMessageBox.prompt('请填写驳回原因','驳回预约',{inputValidator:v=>!!v||'必须填写原因'}).then(r=>r.value);else await ElMessageBox.confirm(`确认批准“${row.title}”吗？系统将再次校验冲突。`,'批准预约',{type:'success'});await http.post(`/admin/approvals/${row.id}`,{action,comment});ElMessage.success(action==='APPROVE'?'预约已批准':'预约已驳回');load()}onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><h2>预约审批</h2><p>处理员工申请，批准前系统会再次执行资源冲突校验</p></div><el-tag type="warning" size="large">待处理 {{rows.length}} 项</el-tag></div><section class="panel"><el-table :data="rows" empty-text="当前没有待审批申请"><el-table-column prop="code" label="预约编号" width="155"/><el-table-column prop="title" label="会议主题" min-width="180"/><el-table-column label="申请人" width="130"><template #default="s">{{s.row.creator.name}}<small class="dept">{{s.row.creator.department?.name}}</small></template></el-table-column><el-table-column prop="room.name" label="会议室" width="125"/><el-table-column label="时间" width="195"><template #default="s">{{dayjs(s.row.startTime).format('MM-DD HH:mm')}} - {{dayjs(s.row.endTime).format('HH:mm')}}</template></el-table-column><el-table-column prop="attendeeCount" label="人数" width="65"/><el-table-column label="操作" width="155" fixed="right"><template #default="s"><el-button type="success" link @click="decide(s.row,'APPROVE')">批准</el-button><el-button type="danger" link @click="decide(s.row,'REJECT')">驳回</el-button></template></el-table-column></el-table></section></div></template><style scoped>.dept{display:block;color:#9aa4b4;margin-top:4px}</style>
